<script setup lang="ts">
import{ref,computed,watch}from'vue';import{useRoute}from'vue-router';import{http}from'../../api/http';import{useAuthStore}from'../../stores/auth';import RecordPage from '../../components/RecordPage.vue';import type {Definition,Row} from '../../shared/records';import RemoteSelect from '../../components/RemoteSelect.vue';import PrivateUpload from'../../components/PrivateUpload.vue'
const auth=useAuthStore(),statusFilter=ref(String(useRoute().query.status??'')),dateFilter=ref(String(useRoute().query.date??'')),paymentRows=ref<Row[]>([]),route=useRoute(),page=ref<InstanceType<typeof RecordPage>>(),selected=ref<Row|null>(null),dialog=ref(''),detail=ref<Row>({items:[]}),error=ref(''),message=ref(''),pending=ref(false),channel=ref('MOCK_A'),channels=ref<string[]>([]),reason=ref(''),voucher=ref(''),rating=ref(5),content=ref(''),images=ref<number[]>([]),reviewItem=ref<number>(),family=computed(()=>route.path.startsWith('/family')),canteen=computed(()=>route.path.startsWith('/canteen'))
const elderFilter=ref<number>(),mealFilter=ref(''),fromFilter=ref(''),toFilter=ref('')
const definition=computed<Definition>(()=>({title:family.value?(route.path.endsWith('/payments')?'支付与消费账单':'我的订单'):canteen.value?'订单备餐出餐':'网点订单',endpoint:'/orders?'+new URLSearchParams({...elderFilter.value?{elderId:String(elderFilter.value)}:{},...mealFilter.value?{mealType:mealFilter.value}:{},...fromFilter.value?{dateFrom:fromFilter.value}:{},...toFilter.value?{dateTo:toFilter.value}:{},...statusFilter.value?{status:statusFilter.value}:{},...dateFilter.value?{date:dateFilter.value}:{},...!family.value&&auth.currentSiteId?{siteId:String(auth.currentSiteId)}:{}}).toString(),columns:[['orderNo','订单号'],['elderName','老人'],['mealDate','用餐日期'],['mealType','餐次'],['status','状态'],['payableAmount','应付金额'],['exceptionNote','异常说明']]}))
async function open(row:Row,type:string){error.value='';message.value='';selected.value=row;try{detail.value=await http.get(`/orders/${row.id}`);paymentRows.value=await http.get(`/orders/${row.id}/payments`);reason.value='';if(type==='pay'){channels.value=await http.get('/payment/channels');if(!channels.value.includes(channel.value))channel.value=channels.value[0]??'';}if(type==='voucher')voucher.value=(await http.get<never,Row>(`/orders/${row.id}/pickup-voucher`)).voucher;if(type==='review'){reviewItem.value=detail.value.items[0]?.id;rating.value=5;content.value='';images.value=[]}dialog.value=type}catch(e){error.value=(e as Error).message}}
async function perform(action:string){if(pending.value)return;pending.value=true;error.value='';try{const id=selected.value!.id;if(action==='pay'){const payment=await http.post<never,Row>(`/orders/${id}/payments`,{channel:channel.value});if(channel.value!=='WALLET')await http.post(`/dev/payments/${payment.id}/simulate-success`);message.value=channel.value==='WALLET'?'钱包支付成功':'模拟支付成功';window.dispatchEvent(new Event('meal:wallet-updated'))}else if(action==='cancel')await http.post(`/orders/${id}/cancel`,{reason:reason.value});else if(action==='exception')await http.patch(`/orders/${id}/exception`,{exceptionFlag:true,exceptionNote:reason.value});else if(action==='review')await http.post('/reviews',{orderItemId:reviewItem.value,rating:rating.value,content:content.value,imageFileIds:images.value});dialog.value='';await page.value?.load()}catch(e){error.value=(e as Error).message}finally{pending.value=false}}
async function prepare(row:Row,ready:boolean){try{await http.post(`/orders/${row.id}/${ready?'ready':'start-preparing'}`);await page.value?.load()}catch(e){error.value=(e as Error).message}}
watch(()=>route.query.status,v=>statusFilter.value=String(v??''))
watch(()=>route.query.orderId,id=>{if(id&&Number.isSafeInteger(Number(id))&&Number(id)>0)void open({id:Number(id)},'detail')},{immediate:true})
</script>
<template><section><el-alert v-if="error" :title="error" type="error" :closable="false" role="alert"/><el-alert v-if="message" :title="message" type="success" :closable="false"/><RecordPage ref="page" :definition="definition"><template #intro><div class="toolbar"><RemoteSelect v-if="!canteen" v-model="elderFilter" source="/elders" label="筛选老人"/><el-select v-model="mealFilter" clearable aria-label="订单餐次筛选"><el-option label="午餐" value="LUNCH"/><el-option label="晚餐" value="DINNER"/></el-select><label for="order-from">起始日期</label><el-input id="order-from" v-model="fromFilter" type="date"/><label for="order-to">结束日期</label><el-input id="order-to" v-model="toFilter" type="date"/><label for="filter-date">用餐日期筛选</label><el-input id="filter-date" v-model="dateFilter" type="date"/><el-select v-model="statusFilter" clearable aria-label="订单状态筛选"><el-option v-for="(label,key) in {PENDING_PAYMENT:'待支付',PAID:'已支付',PREPARING:'备餐中',READY:'待取餐',COMPLETED:'已完成',CANCEL_REQUESTED:'申请取消',CANCELLED:'已取消',REFUNDED:'已退款'}" :key="key" :label="label" :value="key"/></el-select></div></template><template #actions="{row}"><el-button link type="primary" @click="open(row,'detail')">详情</el-button><el-button v-if="!canteen&&row.status==='PENDING_PAYMENT'" link type="primary" @click="open(row,'pay')">支付</el-button><el-button v-if="!canteen&&['PENDING_PAYMENT','PAID'].includes(row.status)" link @click="open(row,'cancel')">取消或退款</el-button><el-button v-if="!canteen&&['PAID','PREPARING','READY'].includes(row.status)&&row.deliveryType!=='DELIVERY'" link @click="open(row,'voucher')">取餐凭证</el-button><el-button v-if="canteen&&row.status==='PAID'" link type="primary" @click="prepare(row,false)">开始备餐</el-button><el-button v-if="canteen&&row.status==='PREPARING'" link type="primary" @click="prepare(row,true)">确认出餐</el-button><el-button v-if="!family&&!canteen" link @click="open(row,'exception')">记录异常</el-button><el-button v-if="family&&row.status==='COMPLETED'" link @click="open(row,'review')">评价菜品</el-button></template></RecordPage>
<el-dialog :model-value="!!dialog" :title="({pay:'订单支付',cancel:'取消或退款申请',voucher:'电子取餐凭证',detail:'订单详情',exception:'异常订单联系记录',review:'评价已消费菜品'} as Row)[dialog]" width="min(700px,94vw)" @close="dialog=''">
<el-alert v-if="error" :title="error" type="error" :closable="false"/><p>{{detail.orderNo}} · {{detail.elderName}} · {{detail.mealDate}}</p><el-table :data="detail.items"><el-table-column prop="dishNameSnapshot" label="菜品"/><el-table-column prop="qty" label="份数"/><el-table-column prop="actualUnitPrice" label="单价"/></el-table><p>原价 ¥{{detail.originalAmount}} − 补贴 ¥{{detail.subsidyAmount}} = 应付 ¥{{detail.payableAmount}}</p>
<template v-if="dialog==='detail'"><h3>订单进度</h3><p v-if="!detail.events?.length">此历史订单暂无进度记录。</p><ol><li v-for="(event,index) in detail.events" :key="index">{{event.label}} · {{new Date(event.createdAt).toLocaleString('zh-CN')}}</li></ol><p v-if="detail.delivery">配送状态：{{detail.delivery.status==='DELIVERED'?'已送达':detail.delivery.status==='OUT_FOR_DELIVERY'?'配送中':'待配送'}}</p><p v-if="detail.paymentExpiresAt&&detail.status==='PENDING_PAYMENT'">支付截止：{{new Date(detail.paymentExpiresAt).toLocaleString('zh-CN')}}</p><h3>支付流水</h3><el-table :data="paymentRows" empty-text="尚未发起支付"><el-table-column prop="paymentNo" label="支付单号" min-width="180"/><el-table-column prop="amount" label="支付金额"/><el-table-column label="状态"><template #default="{row}">{{row.status==='SUCCESS'?'支付成功':'待确认'}}</template></el-table-column><el-table-column prop="channel" label="渠道"/><el-table-column prop="paidAt" label="支付时间 UTC" min-width="180"/></el-table><p v-if="detail.exceptionNote">异常联系记录：{{detail.exceptionNote}}</p></template><template v-if="dialog==='pay'"><el-alert v-if="channel!=='WALLET'" title="本地演示支付，仅用于业务测试" type="info" :closable="false"/><el-select v-model="channel" aria-label="支付渠道"><el-option v-for="c in channels" :key="c" :value="c" :label="c==='WALLET'?'钱包余额支付':c==='MOCK_A'?'演示支付 A（模拟）':'演示支付 B（模拟）'"/></el-select><el-button type="primary" :disabled="!channels.length" :loading="pending" @click="perform('pay')">{{channel==='WALLET'?'确认钱包支付':'模拟支付并确认'}}</el-button></template>
<template v-if="dialog==='voucher'"><p>到网点取餐时，请出示以下一次性凭证：</p><code style="word-break:break-all;font-size:20px" data-testid="pickup-voucher">{{voucher}}</code></template><template v-if="dialog==='cancel'||dialog==='exception'"><label for="order-note">原因或联系记录</label><el-input id="order-note" v-model="reason" type="textarea"/><el-button type="primary" :loading="pending" @click="perform(dialog)">确认提交</el-button></template>
<template v-if="dialog==='review'"><div class="form-stack"><el-select v-model="reviewItem" aria-label="评价菜品"><el-option v-for="item in detail.items" :key="item.id" :value="item.id" :label="item.dishNameSnapshot"/></el-select><el-rate v-model="rating" :max="5"/><label for="review-content">评价内容</label><el-input id="review-content" v-model="content" type="textarea"/><PrivateUpload v-model="images" purpose="REVIEW"/><el-button type="primary" :loading="pending" @click="perform('review')">提交评价</el-button></div></template></el-dialog></section></template>
